def rot90(grid):
    n = len(grid)
    return [[grid[n-1-j][i] for j in range(n)] for i in range(n)]

def rot180(grid):
    return rot90(rot90(grid))

def rot270(grid):
    return rot90(rot90(rot90(grid)))

def build_pinwheel(q_tl, q_tr, q_bl, q_br):
    h, w = 6, 6
    q_size = 3
    output = [[0]*w for _ in range(h)]

    # TL no rotation
    for i in range(q_size):
        for j in range(q_size):
            output[i][j] = q_tl[i][j]
    # TR 90 deg rotation
    for i in range(q_size):
        for j in range(q_size):
            output[i][j+q_size] = q_tr[i][j]
    # BL 270 deg rotation
    for i in range(q_size):
        for j in range(q_size):
            output[i+q_size][j] = q_bl[i][j]
    # BR 180 deg rotation
    for i in range(q_size):
        for j in range(q_size):
            output[i+q_size][j+q_size] = q_br[i][j]
    return output

